function newSchoolState(name,school=''){return{teacher:name,school,region:'',inspection:'',year:'',term:'',className:'',classNameFr:'',classCode:'',subjects:[],pupils:[],marks:[],terms:[],marksByTerm:{},classes:[],activeClassId:'',classData:{}}}
